35	import org.springframework.samples.petclinic.model.Owner;
36	import org.springframework.samples.petclinic.model.Pet;
37	import org.springframework.samples.petclinic.model.Visit;
38	import org.springframework.samples.petclinic.rest.advice.OwnerCreationRejectedException;
39	import org.springframework.samples.petclinic.rest.api.OwnersApi;
40	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
41	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.PetDto;
43	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
46	import org.springframework.samples.petclinic.service.ClinicService;
47	import org.springframework.samples.petclinic.service.IdempotencyStore;
48	import org.springframework.samples.petclinic.util.BusinessDays;
49	import org.springframework.security.access.prepost.PreAuthorize;
50	import org.springframework.web.bind.annotation.CrossOrigin;
51	import org.springframework.web.bind.annotation.RequestMapping;
52	import org.springframework.web.bind.annotation.RestController;
53	import org.springframework.web.util.UriComponentsBuilder;
54	
55	import jakarta.servlet.http.HttpServletRequest;
56	import jakarta.transaction.Transactional;
57	
58	/**
59	 * @author Vitaliy Fedoriv
60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    /** Dedicated audit logger: on a successful create an audit line records the owner id,
68	     * memberId and registrationDate. */
69	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
70	
71	    /** Dedicated notification logger: on a successful create a welcome notification is enqueued,
72	     * recording the owner id and memberId. */
73	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
74	
75	    /** Serializes the structured {@link OwnerCreatedEvent} emitted on each create. */
76	    private static final ObjectMapper AUDIT_MAPPER = JsonMapper.builder().build();
77	
78	    /** Monotonically increasing sequence number assigned to each successful create's audit event. */
79	    private static final AtomicLong AUDIT_EVENT_SEQ = new AtomicLong();
80	
81	    /** Maximum number of owners permitted in a single city; the create is rejected at this count. */
82	    private static final int CITY_CAPACITY = 50;
83	
84	    /** Once a city already holds at least this many owners (but fewer than {@link #CITY_CAPACITY}),
85	     * a new owner created for that city is flagged with {@code capacityWarning} to signal the city
86	     * is approaching its capacity limit. */
87	    private static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;
88	
89	    /** Maximum number of owners that may be created on a single day (by registrationDate); the
90	     * create is rejected once this many owners already carry today's registration date. */
91	    private static final int DAILY_REGISTRATION_LIMIT = 100;
92	
93	    /** Once more than this many owners already carry a given day's registration date, a new owner
94	     * created for that day is flagged with {@code bulkSignupWarning} to signal a bulk-signup surge. */
95	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
96	
97	    /** HTTP header carrying the client-supplied idempotency key for a create. */
98	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
99	
100	    private final ClinicService clinicService;
101	
102	    private final OwnerMapper ownerMapper;
103	
104	    private final PetMapper petMapper;
105	
106	    private final VisitMapper visitMapper;
107	
108	    private final HttpServletRequest request;
109	
110	    private final IdempotencyStore idempotencyStore;
111	
112	    public OwnerRestControllerV1(ClinicService clinicService,
113	                                 OwnerMapper ownerMapper,
114	                                 PetMapper petMapper,
115	                                 VisitMapper visitMapper,
116	                                 HttpServletRequest request,
117	                                 IdempotencyStore idempotencyStore) {
118	        this.clinicService = clinicService;
119	        this.ownerMapper = ownerMapper;
120	        this.petMapper = petMapper;
121	        this.visitMapper = visitMapper;
122	        this.request = request;
123	        this.idempotencyStore = idempotencyStore;
124	    }
125	
126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
129	        Collection<Owner> owners;
130	        if (lastName != null) {
131	            owners = this.clinicService.findOwnerByLastName(lastName);
132	        } else {
133	            owners = this.clinicService.findAllOwners();
134	        }
135	        if (owners.isEmpty()) {
136	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
137	        }
138	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
139	    }
140	
141	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
142	    @Override
143	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
144	        Owner owner = this.clinicService.findOwnerById(ownerId);
145	        if (owner == null) {
146	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
147	        }
148	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
149	    }
150	
151	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
152	    @Override
153	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
154	        // Idempotent create: if this request carries an Idempotency-Key we have already created an
155	        // owner for, return that original owner with 200 OK instead of creating a duplicate.
156	        String idempotencyKey = request.getHeader(IDEMPOTENCY_KEY_HEADER);
157	        boolean hasIdempotencyKey = idempotencyKey != null && !idempotencyKey.isBlank();
158	        if (hasIdempotencyKey) {
159	            Optional<Owner> existing = this.idempotencyStore.find(idempotencyKey)
160	                .map(this.clinicService::findOwnerById);
161	            if (existing.isPresent()) {
162	                return new ResponseEntity<>(ownerMapper.toOwnerDto(existing.get()), HttpStatus.OK);
163	            }
164	        }
165	        HttpHeaders headers = new HttpHeaders();
166	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
167	        // The effective registration date (supplied, or the server date when omitted) must fall on
168	        // a business day: a weekend rolls forward to the next Monday. Everything derived from the
169	        // registration date — the stored value, the per-day limit below and the membership number —
170	        // uses this adjusted date.
171	        LocalDate effectiveDate = BusinessDays.effectiveRegistrationDate(owner.getRegistrationDate());
172	        owner.setRegistrationDate(effectiveDate);
173	        // Per-day capacity: once the day has reached its limit of newly created owners, reject
174	        // further creates for that day with 429 Too Many Requests.
175	        int ownersRegisteredToday = this.clinicService.countOwnersRegisteredOn(effectiveDate);
176	        if (ownersRegisteredToday >= DAILY_REGISTRATION_LIMIT) {
177	            throw new OwnerCreationRejectedException(HttpStatus.TOO_MANY_REQUESTS,
178	                "The daily owner registration limit has been reached; please try again later");
179	        }
180	        // Bulk-signup warning: flag this owner when more than 80 owners have already been created
181	        // for its registration date, signalling a bulk-signup surge.
182	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
183	        // Per-city capacity: a city that already holds the maximum number of owners is full.
184	        int ownersInCity = this.clinicService.countOwnersInCity(owner.getCity());
185	        if (ownersInCity >= CITY_CAPACITY) {
186	            throw new OwnerCreationRejectedException(HttpStatus.CONFLICT,
187	                "The city has reached its maximum owner capacity");
188	        }
189	        // Capacity warning: flag this owner when its city already holds between the warning
190	        // threshold (40) and the hard limit (49), signalling the city is approaching capacity.
191	        owner.setCapacityWarning(ownersInCity >= CITY_CAPACITY_WARNING_THRESHOLD);
192	        // The household id is derived deterministically on the owner itself (see
193	        // Owner.getHouseholdId()) from its normalized last name and postcode, so owners sharing a
194	        // last name and postcode share it automatically — no linking step and no ordering to manage.
195	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
196	        // Exact-identity hard duplicate: reject with 409 when the new owner's WHOLE identityKey
197	        // (the SHA-256 of normalized telephone | lower-cased email-or-empty | soundex(lastName))
198	        // equals an existing owner's. A truly identical record is always rejected, independent of
199	        // sharesHousehold.
200	        if (this.clinicService.isIdentityKeyInUse(owner)) {
201	            throw new OwnerCreationRejectedException(HttpStatus.CONFLICT,
202	                "An owner with the same identity already exists");
203	        }
204	        // Household membership: another owner may already belong to this (last name, postcode)
205	        // household. A new member is admitted rather than rejected — its membership level is instead
206	        // capped relative to the household (see below). An undeclared member (sharesHousehold not
207	        // set) that is not an exact-identity duplicate is still allowed through, flagged as a
208	        // possible duplicate for review.
209	        boolean householdInUse = this.clinicService.isHouseholdInUse(owner);
210	        // Soft "possible duplicate" detection: an existing owner's last name has the same Soundex
211	        // code and the same postcode, while its identity key differs (so it is not a hard
212	        // duplicate). A declared household member (sharesHousehold on an in-use household) is an
213	        // intentional share, not a suspected duplicate, so it is not flagged; otherwise the create
214	        // still proceeds, flagged with possibleDuplicate=true and possibleDuplicateOf set to the
215	        // matching owner id.
216	        Integer possibleDuplicateOf = (householdInUse && sharesHousehold)
217	            ? null
218	            : this.clinicService.findPossibleDuplicateOwnerId(owner);
219	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
220	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
221	        owner.setNamesakeCount(
222	            this.clinicService.countNamesakes(owner.getFirstName(), owner.getLastName()));
223	        // Membership-level ceiling: a new owner's membershipLevel may not exceed one above the
224	        // current maximum level among its existing household members. Derive the cap from those
225	        // members' effective (already-capped) levels; with no existing member the cap stays null
226	        // and the owner's level is used uncapped.
227	        Collection<Owner> householdMembers = this.clinicService.findHouseholdMembers(owner);
228	        if (!householdMembers.isEmpty()) {
229	            int maxHouseholdLevel = householdMembers.stream()
230	                .mapToInt(member -> ownerMapper.formatMembershipLevel(member))
231	                .max()
232	                .getAsInt();
233	            owner.setMembershipLevelCap(maxHouseholdLevel + 1);
234	        }
235	        this.clinicService.saveOwner(owner);
236	        // Compute the derived membership level once so the human-readable line and the structured
237	        // event below are guaranteed to report the identical value.
238	        int membershipLevel = ownerMapper.formatMembershipLevel(owner);
239	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
240	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), membershipLevel);
241	        // In addition to the human-readable audit line above, emit an immutable structured event.
242	        // This is the schema-version-2 event: it carries schemaVersion=2, the owner's current
243	        // primary identifier (the version-2 memberId) via Owner.getPrimaryIdentifier(), the owner
244	        // segment recomputed from the version-2 identity, and a sequence number that strictly
245	        // increases across creates.
246	        OwnerCreatedEvent event = new OwnerCreatedEvent(
247	            OwnerCreatedEvent.SCHEMA_VERSION, AUDIT_EVENT_SEQ.incrementAndGet(), owner.getId(),
248	            owner.getPrimaryIdentifier(), membershipLevel, ownerMapper.formatOwnerSegment(owner),
249	            OwnerCreatedEvent.EVENT_TYPE);
250	        AUDIT.info(AUDIT_MAPPER.writeValueAsString(event));
251	        // Enqueue a welcome notification for the newly created owner, recording the owner id and
252	        // memberId so the notification pipeline can address the member.
253	        NOTIFY.info("welcome notification enqueued for owner id={} memberId={}",
254	            owner.getId(), owner.getMemberId());
255	        if (hasIdempotencyKey) {
256	            this.idempotencyStore.record(idempotencyKey, owner.getId());
257	        }
258	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
259	        headers.setLocation(UriComponentsBuilder.newInstance()
260	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
261	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
262	    }
263	
264	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
265	    @Override
266	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
267	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
268	        if (currentOwner == null) {
269	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
270	        }
271	        currentOwner.setAddressLine1(ownerMapper.normalizeAddress(ownerFieldsDto.getAddressLine1()));
272	        currentOwner.setAddressLine2(ownerMapper.normalizeAddress(ownerFieldsDto.getAddressLine2()));
273	        currentOwner.setAddress(ownerMapper.composeAddress(ownerFieldsDto));
274	        currentOwner.setCity(ownerFieldsDto.getCity());
275	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
276	        currentOwner.setLastName(ownerFieldsDto.getLastName());
277	        currentOwner.setTelephone(ownerMapper.normalizeTelephone(ownerFieldsDto.getTelephone()));
278	        currentOwner.setEmail(ownerMapper.normalizeEmail(ownerFieldsDto.getEmail()));
279	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
280	        this.clinicService.saveOwner(currentOwner);
281	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
282	    }
283	
284	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
285	    @Transactional
286	    @Override
287	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
288	        Owner owner = this.clinicService.findOwnerById(ownerId);
289	        if (owner == null) {
290	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
291	        }
292	        this.clinicService.deleteOwner(owner);
293	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
294	    }
295	
296	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
297	    @Override
298	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
299	        Owner owner = this.clinicService.findOwnerById(ownerId);
300	        if (owner == null) {
301	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
302	        }
303	        HttpHeaders headers = new HttpHeaders();
304	        Pet pet = petMapper.toPet(petFieldsDto);
305	        owner.setId(ownerId);
306	        pet.setOwner(owner);
307	        pet.getType().setName(null);
308	        this.clinicService.savePet(pet);
309	        PetDto petDto = petMapper.toPetDto(pet);
310	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
311	            .buildAndExpand(pet.getId()).toUri());
312	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
313	    }
314	
315	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
316	    @Override
317	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
318	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
319	        if (currentOwner != null) {
320	            Pet currentPet = this.clinicService.findPetById(petId);
321	            if (currentPet != null) {
322	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
323	                currentPet.setName(petFieldsDto.getName());
324	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
325	                this.clinicService.savePet(currentPet);
326	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
327	            }
328	        }
329	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
330	    }
331	
332	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
333	    @Override
334	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
335	        HttpHeaders headers = new HttpHeaders();
336	        Visit visit = visitMapper.toVisit(visitFieldsDto);
337	        Pet pet = new Pet();
338	        pet.setId(petId);
339	        visit.setPet(pet);
340	        this.clinicService.saveVisit(visit);
341	        VisitDto visitDto = visitMapper.toVisitDto(visit);
342	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
343	            .buildAndExpand(visit.getId()).toUri());
344	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
345	    }
346	
347	
348	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
349	    @Override
350	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
351	        Owner owner = this.clinicService.findOwnerById(ownerId);
352	        if (owner != null) {
353	            Pet pet = owner.getPet(petId);
354	            if (pet != null) {
355	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
356	            }
357	        }
358	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
359	    }
360	}
