package org.springframework.samples.petclinic.rest.advice;

import org.springframework.http.HttpStatus;

/**
 * Signals that a create request was rejected by a business rule (for example a capacity, duplicate
 * or rate limit). It carries the HTTP status to report so that {@link ExceptionControllerAdvice}
 * can render a matching RFC&nbsp;7807 {@code application/problem+json} response; the exception
 * message becomes the problem detail.
 */
public class OwnerCreationRejectedException extends RuntimeException {

    private final HttpStatus status;

    public OwnerCreationRejectedException(HttpStatus status, String detail) {
        super(detail);
        this.status = status;
    }

    public HttpStatus getStatus() {
        return this.status;
    }
}

