59	    @NotEmpty
60	    private String city;
61	
62	    @Column(name = "telephone")
63	    @NotEmpty
64	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
65	    private String telephone;
66	
67	    @Column(name = "email")
68	    @Email
69	    private String email;
70	
71	    @Column(name = "postcode")
72	    private String postcode;
73	
74	    @Column(name = "registration_date")
75	    private LocalDate registrationDate;
76	
77	    @Column(name = "birth_date")
78	    private LocalDate birthDate;
79	
80	    @Column(name = "member_id")
81	    private String memberId;
82	
83	    @Column(name = "namesake_count")
84	    private Integer namesakeCount;
85	
86	    @Column(name = "bulk_signup_warning")
87	    private Boolean bulkSignupWarning;
88	
89	    @Column(name = "capacity_warning")
90	    private Boolean capacityWarning;
91	
92	    @Column(name = "possible_duplicate")
93	    private Boolean possibleDuplicate;
94	
95	    @Column(name = "possible_duplicate_of")
96	    private Integer possibleDuplicateOf;
97	
98	    @Column(name = "membership_level_cap")
99	    private Integer membershipLevelCap;
100	
101	    @Column(name = "deleted")
102	    private boolean deleted;
103	
104	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
105	    private Set<Pet> pets;
106	
107	    public String getAddress() {
108	        return this.address;
109	    }
110	
111	    public void setAddress(String address) {
112	        this.address = address;
113	    }
114	
115	    public String getAddressLine1() {
116	        return this.addressLine1;
117	    }
