140	        return this.city;
141	    }
142	
143	    public void setCity(String city) {
144	        this.city = city;
145	    }
146	
147	    public String getTelephone() {
148	        return this.telephone;
149	    }
150	
151	    public void setTelephone(String telephone) {
152	        this.telephone = telephone;
153	    }
154	
155	    public String getEmail() {
156	        return this.email;
157	    }
158	
159	    public void setEmail(String email) {
160	        this.email = email;
161	    }
162	
163	    public String getPostcode() {
164	        return this.postcode;
165	    }
166	
167	    public void setPostcode(String postcode) {
168	        this.postcode = postcode;
169	    }
170	
171	    public LocalDate getRegistrationDate() {
172	        return this.registrationDate;
173	    }
174	
175	    public void setRegistrationDate(LocalDate registrationDate) {
176	        this.registrationDate = registrationDate;
177	    }
178	
179	    public LocalDate getBirthDate() {
180	        return this.birthDate;
181	    }
182	
183	    public void setBirthDate(LocalDate birthDate) {
184	        this.birthDate = birthDate;
185	    }
186	
187	    public String getMemberId() {
188	        return this.memberId;
189	    }
190	
191	    public void setMemberId(String memberId) {
192	        this.memberId = memberId;
193	    }
194	
195	    /**
196	     * The owner's current primary identifier, i.e. whatever external reference presently identifies
197	     * this owner as a member. That is the unified {@link #getMemberId() memberId}. Reading the
198	     * identifier through this single accessor lets callers track the current identifier without
199	     * depending on its field name at their call site.
200	     */
201	    @Transient
202	    public String getPrimaryIdentifier() {
203	        return getMemberId();
204	    }
205	
206	    public Integer getNamesakeCount() {
207	        return this.namesakeCount;
208	    }
209	
210	    public void setNamesakeCount(Integer namesakeCount) {
211	        this.namesakeCount = namesakeCount;
212	    }
