266	        this.deleted = deleted;
267	    }
268	
269	    /**
270	     * When no registration date is supplied, default it to the server's current date, then roll
271	     * the effective date forward onto a business day: a Saturday or Sunday becomes the following
272	     * Monday. Running on {@link PrePersist} keeps both invariants true for every create path
273	     * (any controller, bulk import or test fixture) rather than a single entry point. The roll is
274	     * idempotent, so a date already adjusted by a caller is left unchanged.
275	     */
276	    @PrePersist
277	    protected void onCreate() {
278	        this.registrationDate = BusinessDays.effectiveRegistrationDate(this.registrationDate);
279	    }
280	
281	    /**
282	     * The fixed version tag mixed into every version-2 owner identifier, the single source of
283	     * truth for which is {@link Regions#VERSION_TAG}. It is prepended to the hashed input of the
284	     * derived {@link #getIdentityKey() identityKey} and {@link #getHouseholdId() householdId}, and
285	     * (via {@link Regions#forPostcodeV2}) into the region segment of the {@code memberId}, so all
286	     * three derivations provably share one tag value and every version-2 identifier differs from
287	     * the value the version-1 algorithm produced. The tag is confined to the identifiers: the
288	     * user-facing {@code locality}, {@code timezone} and owner-segment region remain the plain
289	     * region code.
290	     */
291	    public static final String IDENTITY_VERSION_TAG = Regions.VERSION_TAG;
292	
293	    /**
294	     * The single derived key behind all duplicate detection, rederived with the version-2
295	     * algorithm: the lower-case hex SHA-256 (64 hex characters) of
296	     * {@code V2|<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>}, where the fixed
297	     * {@value #IDENTITY_VERSION_TAG} version tag is mixed in first, the telephone is the stored
298	     * (normalized) value or an empty string when absent, the email is lower-cased or an empty
299	     * string when absent, and the surname component is the standard Soundex code of the last name
300	     * (see {@link org.springframework.samples.petclinic.util.Soundex}). Mixing in the version tag
301	     * means no value the version-1 algorithm produced is produced again. Because the telephone is
302	     * part of the key, two owners are duplicates only when their WHOLE identity keys are equal; two
303	     * owners sharing a surname (hence Soundex) and postcode but with different telephones have
304	     * different identity keys and are therefore both allowed, surfacing instead as a soft
305	     * possible-duplicate match.
306	     */
307	    @Transient
308	    public String getIdentityKey() {
309	        String telephone = this.telephone == null ? "" : this.telephone;
310	        String email = this.email == null ? "" : this.email.toLowerCase();
311	        String key = IDENTITY_VERSION_TAG + "|" + telephone + "|" + email + "|" + Soundex.encode(getLastName());
312	        return sha256Hex(key, 32);
313	    }
314	
315	    /**
316	     * The deterministic household identifier derived from the owner's own fields, rederived with
317	     * the version-2 algorithm and mirroring {@link #getIdentityKey()}: the first twelve lower-case
318	     * hex characters (the first six bytes) of the SHA-256 of
319	     * {@code V2|<normalizedLastName>|<postcode>}, where the fixed {@value #IDENTITY_VERSION_TAG}
320	     * version tag is mixed in first, the last name is normalized by trimming, collapsing internal
321	     * whitespace and lower-casing, and an absent postcode counts as empty. Mixing in the version
322	     * tag means no value the version-1 algorithm produced is produced again. Because it is a pure
323	     * function of the stored last name and postcode, every owner sharing both automatically carries
324	     * the same value, with no linking step or stored column.
325	     */
326	    @Transient
327	    public String getHouseholdId() {
328	        String lastName = getLastName() == null ? ""
329	            : getLastName().trim().replaceAll("\\s+", " ").toLowerCase();
330	        String key = IDENTITY_VERSION_TAG + "|" + lastName + "|" + (this.postcode == null ? "" : this.postcode);
331	        return sha256Hex(key, 6);
332	    }
333	
334	    /**
335	     * The lower-case hex SHA-256 of {@code value}, truncated to the first {@code bytes} bytes
336	     * (so {@code 2 * bytes} hex characters). Shared by the derived identity and household keys so
337	     * the two stay consistent; they differ only in how many leading bytes they keep.
338	     */
339	    private static String sha256Hex(String value, int bytes) {
340	        try {
341	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
342	            StringBuilder sb = new StringBuilder(bytes * 2);
343	            for (int i = 0; i < bytes; i++) {
344	                sb.append(String.format("%02x", digest[i]));
345	            }
346	            return sb.toString();
347	        }
348	        catch (NoSuchAlgorithmException e) {
349	            throw new IllegalStateException("SHA-256 not available", e);
350	        }
351	    }
352	
353	    protected Set<Pet> getPetsInternal() {
354	        if (this.pets == null) {
355	            this.pets = new HashSet<>();
356	        }
357	        return this.pets;
358	    }
359	
360	    protected void setPetsInternal(Set<Pet> pets) {
361	        this.pets = pets;
362	    }
363	
364	    public List<Pet> getPets() {
365	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
366	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
367	        return Collections.unmodifiableList(sortedPets);
368	    }
369	
370	    public void setPets(List<Pet> pets) {
371	        this.pets = new HashSet<>(pets);
372	    }
373	
374	    public void addPet(Pet pet) {
375	        getPetsInternal().add(pet);
376	        pet.setOwner(this);
377	    }
378	
379	    /**
380	     * Return the Pet with the given name, or null if none found for this Owner.
381	     *
382	     * @param name to test
383	     * @return true if pet name is already in use
384	     */
385	    public Pet getPet(String name) {
386	        return getPet(name, false);
387	    }
388	
389	    /**
390	     * Return the Pet with the given name, or null if none found for this Owner.
391	     *
392	     * @param name to test
393	     * @return true if pet name is already in use
394	     */
395	    public Pet getPet(String name, boolean ignoreNew) {
396	        name = name.toLowerCase();
397	        for (Pet pet : getPetsInternal()) {
398	            if (!ignoreNew || !pet.isNew()) {
399	                String compName = pet.getName();
400	                compName = compName.toLowerCase();
401	                if (compName.equals(name)) {
402	                    return pet;
403	                }
404	            }
405	        }
406	        return null;
407	    }
408	
409	    public Pet getPet(Integer petId) {
410	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
411	    }
412	
413	    @Override
414	    public String toString() {
415	        return new ToStringCreator(this)
416	
417	            .append("id", this.getId())
418	            .append("new", this.isNew())
419	            .append("lastName", this.getLastName())
420	            .append("firstName", this.getFirstName())
421	            .append("address", this.address)
422	            .append("addressLine1", this.addressLine1)
423	            .append("addressLine2", this.addressLine2)
424	            .append("city", this.city)
425	            .append("telephone", this.telephone)
426	            .append("email", this.email)
427	            .append("postcode", this.postcode)
428	            .append("registrationDate", this.registrationDate)
429	            .append("birthDate", this.birthDate)
430	            .append("memberId", this.memberId)
431	            .append("householdId", this.getHouseholdId())
432	            .append("namesakeCount", this.namesakeCount)
433	            .append("bulkSignupWarning", this.bulkSignupWarning)
434	            .append("capacityWarning", this.capacityWarning)
435	            .append("possibleDuplicate", this.possibleDuplicate)
436	            .append("possibleDuplicateOf", this.possibleDuplicateOf)
437	            .append("membershipLevelCap", this.membershipLevelCap)
438	            .append("deleted", this.deleted)
439	            .toString();
440	    }
441	}
